from fastapi import FastAPI, Form, File, UploadFile
from fastapi.testclient import TestClient

app = FastAPI()

@app.post("/test-ok")
async def test_ok(file: UploadFile = File(...), form_data: str = Form(...)):
    return {"form_data": form_data, "file": file.filename}

@app.post("/test-fail")
async def test_fail(form_data: str = Form(...), file: UploadFile = File(...)):
    return {"form_data": form_data, "file": file.filename}

client = TestClient(app)

def test_order():
    # Test Case 1: File then Form (Expected to work)
    response_ok = client.post(
        "/test-ok", 
        data={"form_data": "hello"}, 
        files={"file": ("test.txt", b"content")}
    )
    print(f"File then Form: {response_ok.status_code}, {response_ok.json()}")
    assert response_ok.status_code == 200

    # Test Case 2: Form then File (The reported issue)
    response_fail = client.post(
        "/test-fail", 
        data={"form_data": "hello"}, 
        files={"file": ("test.txt", b"content")}
    )
    print(f"Form then File: {response_fail.status_code}, {response_fail.json()}")
    assert response_fail.status_code == 200

if __name__ == "__main__":
    try:
        test_order()
        print("Tests passed!")
    except Exception as e:
        print(f"Tests failed: {e}")
        import sys
        sys.exit(1)

